const items = $input.all();

return items.map(item => {

  let raw = item.json.text ?? item.json.output ?? "";

  let data;

  try {
    if (typeof raw === "object" && raw !== null) {
      data = raw;
    } else {
      // Remove markdown JSON code fences
      raw = String(raw)
        .replace(/```json\s*/gi, "")
        .replace(/```\s*/g, "")
        .trim();

      // Parse JSON output
      data = JSON.parse(raw);
    }
  } catch (error) {
    throw new Error(
      "Invalid AI JSON output: " + error.message
    );
  }

  const to = String(data.to ?? "").trim();
  const subject = String(data.subject ?? "").trim();

  // Normalize line breaks
  const body = String(data.body ?? "")
    .replace(/\\n/g, "\n")
    .replace(/\r\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  // Escape HTML
  const escapeHtml = text => text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

  // Create HTML formatted email
  const html = body
    .split(/\n\s*\n/)
    .map(p =>
      `<p>${escapeHtml(p).replace(/\n/g, "<br>")}</p>`
    )
    .join("\n");

  return {
    json: {
      to,
      subject,
      body,
      html
    }
  };

});
